#!/usr/bin/env python3
# Usage: PYTHONPATH=. python3 scripts/crosscheck_cyclic.py 6 7 8 9 10 11   (n=11 takes ~20 min)
# Prints n and the best distance of any k=1 code generated by the cyclic shifts of one Pauli.
# Unreduced brute force over every seed (no symmetry reduction), independent of spaces.py
import itertools, sys
from probatio.checkers.stabilizer_code import analyse_code, cyclic_shifts, pauli_to_xz, symplectic_product
for n in map(int, sys.argv[1:]):
    best = 0
    for t in itertools.product("IXYZ", repeat=n):
        s = "".join(t)
        if s[0] == "I": continue  # rotation: some rotation starts with non-I unless all-I
        sh = cyclic_shifts(s); a = pauli_to_xz(s)
        if any(symplectic_product(a, pauli_to_xz(x)) for x in sh[1:]): continue
        r = analyse_code(sh)
        if r.get("k") == 1 and r.get("d") and r["d"] > best: best = r["d"]
    print(n, best, flush=True)
